package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_nextElementSibling_TriageGen1Test {

    @Test
    public void testNextElementSibling_ReturnsNextSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a><p></p></div>");
        Element firstP = doc.select("p").first();
        Element secondP = doc.select("p").get(1);

        assertEquals(secondP, firstP.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_ReturnsNullWhenLastSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a></div>");
        Element lastP = doc.select("p").first();

        assertNull(lastP.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_ReturnsNullWhenNoParent() {
        // An element without a parent should result in index being null or parent() returning null
        // Based on the code: List<Element> siblings = parent().children();
        // If parent() is null, it throws NullPointerException. 
        // If parent() exists but element is not in children, indexInList returns null.
        Element standalone = new Element(Tag.valueOf("p"), "");

        // According to the provided code logic: 
        // Integer index = indexInList(this, siblings);
        // Validate.notNull(index); -> This will throw exception if index is null

        try {
            standalone.nextElementSibling();
            fail("Expected exception due to null parent or null index");
        } catch (NullPointerException | IllegalArgumentException e) {
            // This covers the Validate.notNull(index) or parent() being null branch
        }
    }

    @Test
    public void testNextElementSibling_SingleChild() {
        Document doc = Parser.parseBodyFragment("<div><p></p></div>");
        Element p = doc.select("p").first();

        assertNull(p.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_MultipleSiblingsMiddle() {
        Document doc = Parser.parseBodyFragment("<div><span><p></p><p></p><p></p></span></div>");
        Element p1 = doc.select("p").get(0);
        Element p2 = doc.select("p").get(1);
        Element p3 = doc.select("p").get(2);

        assertEquals(p2, p1.nextElementSibling());
        assertEquals(p3, p2.nextElementSibling());
        assertNull(p3.nextElementSibling());
    }
}
